using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Threading;

public class EventListener
{
    private readonly ConcurrentDictionary<string, EventHandler> eventHandlers;
    private readonly ConcurrentDictionary<string, int> eventCounters;

    public EventListener()
    {
        eventHandlers = new ConcurrentDictionary<string, EventHandler>();
        eventCounters = new ConcurrentDictionary<string, int>();
    }

    public void Subscribe(string eventName, EventHandler handler)
    {
        eventHandlers[eventName] = handler;
        eventCounters[eventName] = 0;
    }

    public void Unsubscribe(string eventName)
    {
        eventHandlers.TryRemove(eventName, out _);
        eventCounters.TryRemove(eventName, out _);
    }

    public void FireEvent(string eventName, params object[] args)
    {
        if (eventHandlers.TryGetValue(eventName, out EventHandler handler))
        {
            Interlocked.Increment(ref eventCounters[eventName]);
            ThreadPool.QueueUserWorkItem(_ => handler.Invoke(args));
        }
    }

    public bool IsSubscribed(string eventName)
    {
        return eventHandlers.ContainsKey(eventName);
    }

    public IList<string> GetSubscribedEvents()
    {
        return new List<string>(eventHandlers.Keys);
    }

    public int GetNumSubscribedEvents()
    {
        return eventHandlers.Count;
    }

    public int GetNumEventsFired()
    {
        int totalFired = 0;
        foreach (int count in eventCounters.Values)
        {
            totalFired += count;
        }
        return totalFired;
    }
}

public delegate void EventHandler(params object[] args);
