    }

    public int CountPrimeNumbers()
    {
        if (numbers.Count == 0)
        {
            throw new InvalidOperationException("No numbers entered.");
        }

        return numbers.Count(IsPrime);
    }

    private static bool IsPrime(int number)
    {
        if (number < 2)
