using System;

class Program
{
    static void Main(string[] args)
    {
        string input = "   hello    world   ";
        string output = FormatString(input);

        Console.WriteLine("Formatted string: " + output);
    }

    static string FormatString(string input)
    {
        // Remove leading and trailing spaces
        input = input.Trim();

        // Remove additional spaces between words
        input = RemoveExtraSpaces(input);

        // Convert string to title case
        input = ToTitleCase(input);

        return input;
    }

    static string RemoveExtraSpaces(string input)
    {
        string[] words = input.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
        return string.Join(" ", words);
    }

    static string ToTitleCase(string input)
    {
        return System.Globalization.CultureInfo.CurrentCulture.TextInfo.ToTitleCase(input.ToLower());
    }
}
